        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple or None")
        if not all(isinstance(v, int) for v in protocol_version):
            raise TypeError("protocol_version tuple must contain integers")

    # Retrieve the internal mapping of handlers
    handlers = getattr(cls, "_protocol_handlers", {})
    if not isinstance(handlers, dict):
        raise TypeError("_protocol_handlers must be a dictionary")

    # Filter out any entries that are None (unsupported)
    handlers = {k: v for k, v in handlers.items() if v is not None}

    if protocol_version is None:
        # Return a copy of all supported handlers
        return dict(handlers)

    # Return a single-item dict if the requested version is supported
    handler = handlers.get(protocol_version)
    return {protocol_version: handler} if handler is not None else {}

